      const within = i % 2 === 0;
      const bankAmt = within ? amt + round2((rng() - 0.5) * 0.08) : amt * (1 - (0.005 + rng() * 0.025));
      const l = mkLedger(`${v} invoice ${inv}`, amt, date5, inv);
      const b = mkBank(`${v} payment ${inv}`, bankAmt, date5, inv);
